var i=`0605-zaalouk`;var n=`world-0605`;var a=`MA`;var s=`northern-africa`;var o=4;var l=62;var r={en:`Zaalouk`,ua:`Заалук`};var g={en:`Zaalouk is a Morocco classic prepared with eggplant, tomato, garlic, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Заалук, страва кухні країни Марокко зі складниками: баклажан, помідор, часник, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Roast whole eggplants until soft and smoky, about 30 minutes; cool slightly, peel and chop the pulp before adding it to the sauce.`,ua:`Запечіть баклажани до м’якості й легкого димного аромату близько 30 хвилин, злегка остудіть, зніміть шкірку й подрібніть м’якоть.`,t:[`roasting`],m:30,i:[[`eggplant`,700,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`tomato`,460,`g`],[`garlic`,4,`clove`],[`ground-cumin`,5,`g`],[`sweet-paprika`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`lemon-juice`,26,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var d={slug:i,id:n,country:`MA`,region:s,servings:4,minutes:62,title:r,text:g,steps:u};export{a as country,d as default,n as id,l as minutes,s as region,o as servings,i as slug,u as steps,g as text,r as title};